//! 名前の種類と閉じた範囲の照合（設計書 02-04「範囲引数の解決」）。
use super::{BindingKind, collect::Resolver, lookup::Ctx, lookup::dotted};
use crate::base::{BindingId, Span};
use crate::diag::{DiagBuilder, DiagCode};
use crate::modules::ModuleKind;
use crate::syntax::ast::{EffectRef, NamedType, ScopeArg, ScopeArgKind, ScopeArgs};
use crate::types::builtin::{BuiltinEffectId, find_builtin_effect};
use crate::types::scope::{
    EndpointPattern, HostPattern, InvalidScope, Kind, PathPattern, Port, PortRange, Range,
};

impl Resolver<'_> {
    fn builtin_effect(&self, id: BindingId) -> Option<BuiltinEffectId> {
        let b = self.out.bindings.get(id)?;
        if let BindingKind::BuiltinEffect(e) = b.kind {
            return Some(e);
        }
        let module = self.modules.get(b.module)?;
        if !matches!(module.kind, ModuleKind::Prelude | ModuleKind::Stdlib) {
            return None;
        }
        let path: Vec<_> = module.name.0.iter().skip(1).map(String::as_str).collect();
        find_builtin_effect(&path, &b.name)
    }
    pub(super) fn effect_arguments(&mut self, ctx: &mut Ctx, e: &EffectRef, id: BindingId) {
        let failure = self.out.stdlib("Benitoite.Failure.Fail") == Some(id);
        let kind =
            self.builtin_effect(id)
                .and_then(|b| b.def())
                .and_then(|b| match (b.module, b.name) {
                    (["IO", "File"], "Read" | "Write") => Some(Kind::Path),
                    (["Network", "Http"], "Connect") => Some(Kind::Endpoint),
                    _ => None,
                });
        if let Some(kind) = kind {
            if e.args.is_none() && e.scope.is_none() {
                return;
            }
            match e.scope.as_deref().map(|s| normalize(s, kind)) {
                Some(Ok(range)) => {
                    self.out.scopes.insert(e.id, range);
                }
                Some(Err(error)) => self.scope_error(
                    &dotted(&e.path),
                    kind,
                    e.scope.as_deref().map_or(e.span, ScopeArgs::element_span),
                    error,
                ),
                None => self.scope_error(&dotted(&e.path), kind, e.span, InvalidScope::PathPattern),
            }
            return;
        }
        if failure && e.scope.is_none() && e.args.as_ref().is_some_and(|args| args.len() == 1) {
            if let Some(args) = &e.args {
                for ty in args {
                    self.ty(ctx, ty);
                }
            }
        } else if failure || e.args.is_some() || e.scope.is_some() {
            // 同じ不正な略記の群は一度だけ報告する。
            if e.scope.as_deref().is_none_or(|s| s.element.start == 0) {
                self.out.diagnostics.push(
                    DiagBuilder::new(DiagCode::E0513)
                        .primary(e.span)
                        .arg("name", dotted(&e.path))
                        .arg("count", if failure { "1" } else { "0" })
                        .build(),
                );
            }
        }
    }
    pub(super) fn type_scope(&mut self, t: &NamedType, id: BindingId) {
        let kind = if self.out.stdlib("Benitoite.Scope.PathIn") == Some(id) {
            Some(Kind::Path)
        } else if self.out.stdlib("Benitoite.Network.Http.RequestIn") == Some(id) {
            Some(Kind::Endpoint)
        } else {
            None
        };
        if let Some(kind) = kind
            && !t.args.is_empty()
        {
            self.scope_error(&dotted(&t.path), kind, t.span, InvalidScope::PathPattern);
            return;
        }
        let Some(scope) = &t.scope else {
            return;
        };
        if let Some(kind) = kind {
            match normalize(scope, kind) {
                Ok(range) => {
                    self.out.scopes.insert(t.id, range);
                }
                Err(error) => self.scope_error(&dotted(&t.path), kind, scope.span, error),
            }
        } else {
            self.out.diagnostics.push(
                DiagBuilder::new(DiagCode::E0520)
                    .primary(scope.span)
                    .arg("name", dotted(&t.path))
                    .arg("expectedScopeKind", super::text::NO_SCOPE)
                    .arg("found", super::text::SCOPE_ARGUMENTS)
                    .note("found")
                    .build(),
            );
        }
    }
    fn scope_source(&self, span: Span) -> String {
        self.sources
            .get(span.file)
            .and_then(|source| {
                let start = usize::try_from(span.start.0).ok()?;
                let end = usize::try_from(span.end.0).ok()?;
                let bytes = source.text().get(start..end)?;
                std::str::from_utf8(bytes).ok().map(str::to_owned)
            })
            .unwrap_or_else(|| super::text::SCOPE_ARGUMENTS.into())
    }
    fn scope_error(&mut self, name: &str, kind: Kind, span: Span, error: InvalidScope) {
        if error == InvalidScope::Internal {
            self.internal(super::text::SCOPE_INTERNAL.into());
            return;
        }
        self.out.diagnostics.push(
            DiagBuilder::new(DiagCode::E0520)
                .primary(span)
                .arg("name", name)
                .arg(
                    "expectedScopeKind",
                    match kind {
                        Kind::Path => super::text::PATH_SCOPE,
                        Kind::Endpoint => super::text::ENDPOINT_SCOPE,
                        Kind::Host => super::text::HOST_SCOPE,
                    },
                )
                .arg("found", self.scope_source(span))
                .note("found")
                .build(),
        );
    }
}
fn normalize(scope: &ScopeArgs, kind: Kind) -> Result<Range, InvalidScope> {
    match (kind, scope.selected()) {
        (
            Kind::Path,
            [
                ScopeArg {
                    kind: ScopeArgKind::String(s),
                    ..
                },
            ],
        ) => PathPattern::parse(s).map(Range::Path),
        (
            Kind::Endpoint,
            [
                ScopeArg {
                    kind: ScopeArgKind::String(host),
                    ..
                },
                ScopeArg {
                    kind: ScopeArgKind::Port(lo, hi),
                    ..
                },
            ],
        ) => {
            let host = HostPattern::parse(host)?;
            let lo = lo.parse::<i64>().map_err(|_| InvalidScope::PortBounds)?;
            let hi = hi
                .as_deref()
                .map_or(Ok(lo), str::parse::<i64>)
                .map_err(|_| InvalidScope::PortBounds)?;
            let ports = PortRange::new(
                Port::from_int(lo).ok_or(InvalidScope::PortBounds)?,
                Port::from_int(hi).ok_or(InvalidScope::PortBounds)?,
            )?;
            Ok(Range::Endpoint(EndpointPattern { host, ports }))
        }
        _ => Err(InvalidScope::PathPattern),
    }
}

//! 範囲引数の字句と回復（設計書 02-03「型の解析」）。
use super::{PResult, Parser, text};
use crate::syntax::ast::{ScopeArg, ScopeArgKind, ScopeArgs};
use crate::syntax::token::{IntegerSuffix, Token, TokenKind, TokenValue};

pub(super) fn parse(p: &mut Parser, start: usize) -> PResult<ScopeArgs> {
    let mut items = Vec::new();
    while !p.at(TokenKind::RBracket) {
        let from = p.pos;
        let mut stack = Vec::new();
        let mut strings = 0_usize;
        loop {
            let kind = p.peek_kind();
            if matches!(kind, TokenKind::Eof | TokenKind::Newline) || p.aborted {
                return Err(p.unexpected(text::COMMA_OR_RBRACKET));
            }
            if strings == 0
                && stack.is_empty()
                && matches!(kind, TokenKind::Comma | TokenKind::RBracket)
            {
                break;
            }
            if kind == TokenKind::StrStart {
                strings = strings.saturating_add(1);
            } else if kind == TokenKind::StrEnd {
                strings = strings.saturating_sub(1);
            } else if strings == 0 {
                if matches!(kind, TokenKind::LParen | TokenKind::LBracket) {
                    stack.push(kind);
                } else if matches!(kind, TokenKind::RParen | TokenKind::RBracket) {
                    let expected = if kind == TokenKind::RParen {
                        TokenKind::LParen
                    } else {
                        TokenKind::LBracket
                    };
                    if stack.pop() != Some(expected) {
                        return Err(p.unexpected(text::COMMA_OR_RBRACKET));
                    }
                }
            }
            p.bump();
        }
        let kind = classify(p.tokens.get(from..p.pos).unwrap_or(&[]));
        items.push(ScopeArg {
            span: p.span_from(from),
            kind,
        });
        if !p.eat(TokenKind::Comma) {
            break;
        }
    }
    p.expect(TokenKind::RBracket)?;
    let len = items.len();
    Ok(ScopeArgs {
        span: p.span_from(start),
        items: items.into(),
        element: 0..len,
    })
}

fn classify(tokens: &[Token]) -> ScopeArgKind {
    match tokens {
        [
            Token {
                kind: TokenKind::StringLit,
                value: TokenValue::Str(s),
                ..
            },
        ] => ScopeArgKind::String(s.clone()),
        [one] if one.kind == TokenKind::IntLit => {
            integer(one).map_or(ScopeArgKind::Invalid, |n| ScopeArgKind::Port(n, None))
        }
        [lo, dots, hi]
            if lo.kind == TokenKind::IntLit
                && dots.kind == TokenKind::DotDot
                && hi.kind == TokenKind::IntLit =>
        {
            match (integer(lo), integer(hi)) {
                (Some(lo), Some(hi)) => ScopeArgKind::Port(lo, Some(hi)),
                _ => ScopeArgKind::Invalid,
            }
        }
        _ => ScopeArgKind::Invalid,
    }
}
fn integer(token: &Token) -> Option<String> {
    let (radix, digits, maximum) = match &token.value {
        TokenValue::Int { radix, digits } => (*radix, digits, u64::try_from(i64::MAX).ok()?),
        TokenValue::WidthInt {
            radix,
            digits,
            suffix,
        } => {
            let maximum = match suffix {
                IntegerSuffix::S8 => u64::try_from(i8::MAX).ok()?,
                IntegerSuffix::S16 => u64::try_from(i16::MAX).ok()?,
                IntegerSuffix::S32 => u64::try_from(i32::MAX).ok()?,
                IntegerSuffix::S64 => u64::try_from(i64::MAX).ok()?,
                IntegerSuffix::U8 => u64::from(u8::MAX),
                IntegerSuffix::U16 => u64::from(u16::MAX),
                IntegerSuffix::U32 => u64::from(u32::MAX),
                IntegerSuffix::U64 => u64::MAX,
            };
            (*radix, digits, maximum)
        }
        TokenValue::None
        | TokenValue::Ident(_)
        | TokenValue::Float(_)
        | TokenValue::WidthFloat { .. }
        | TokenValue::Decimal(_)
        | TokenValue::Str(_)
        | TokenValue::Char(_)
        | TokenValue::Symbol(_) => return None,
    };
    let n = u64::from_str_radix(digits, radix).ok()?;
    (n <= maximum).then(|| n.to_string())
}

//! 範囲注釈の通常の解析・名前解決・型検査の接続（設計書 01-02、01-07、02-04）。
// テストの失敗は panic で表す（AGENTS.md「実装の規約」）。
#![allow(clippy::unwrap_used, clippy::panic, clippy::indexing_slicing)]

use benitoite::{
    diag::Diagnostic,
    pipeline::{self, CheckOptions, CheckedProgram},
    syntax::ast::{FnDecl, Item},
    types::{Scheme, Ty, TyNames},
};
use std::collections::BTreeSet;

const IMPORTS: &str = "import Benitoite.Unofficial.IO.File\nimport Benitoite.Unofficial.Network.Http\nimport Benitoite.Unofficial.Failure\n";

fn check(source: &str) -> pipeline::CheckResult {
    pipeline::check_text(
        "scope-annotations.bnt",
        source.as_bytes(),
        CheckOptions {
            require_main: false,
            deny_warnings: false,
        },
    )
}

fn errors(result: &pipeline::CheckResult) -> Vec<&Diagnostic> {
    result.diagnostics.iter().filter(|d| d.is_error()).collect()
}

fn signature<'a>(program: &'a CheckedProgram, name: &str) -> &'a Scheme {
    let (id, _) = program
        .resolved
        .bindings
        .iter()
        .find(|(_, b)| b.name == name)
        .unwrap();
    program.types.decl_types.get(id).unwrap()
}

fn function<'a>(program: &'a CheckedProgram, name: &str) -> &'a FnDecl {
    program
        .asts
        .iter()
        .flat_map(|m| &m.decls)
        .find_map(|d| {
            if let Item::Fn(f) = &d.item
                && f.name.text == name
            {
                Some(f.as_ref())
            } else {
                None
            }
        })
        .unwrap()
}

fn slice(source: &str, span: benitoite::base::Span) -> &str {
    &source[usize::try_from(span.start.0).unwrap()..usize::try_from(span.end.0).unwrap()]
}

// 関門: 通常の構文から原子列への展開・標準束縛の認定・正規化・元位置をまとめて守る。
// 代数だけの既存テストでは、解決時に範囲をTopへ戻す退行や、略記の要素位置の消失を捕まえない。
// 公開のcheck入口を使い、検査専用の差し込み口は設けない。
#[test]
fn scope_shorthand_preserves_atoms_and_source_elements() {
    let source = format!(
        "{IMPORTS}function sample() -> Unit uses File.Write[\"/data/a/**\", \"/data/a/input\",], File.Write, Http.Connect[\"A.Example\", 0x1_bb, \"192.168.1.0/24\", 80..81], Failure.Fail[String]\n ()\nend function\n"
    );
    let checked = check(&source);
    assert!(errors(&checked).is_empty(), "{:?}", checked.diagnostics);
    let program = checked.program.unwrap();
    let scheme = signature(&program, "sample");
    let suffixes = scheme
        .effects
        .names
        .iter()
        .map(|n| n.range().suffix())
        .collect::<BTreeSet<_>>();
    assert_eq!(
        suffixes,
        [
            "",
            "[\"/data/a/**\"]",
            "[\"/data/a/input\"]",
            "[\"a.example\", 443]",
            "[\"192.168.1.0/24\", 80..81]",
        ]
        .into_iter()
        .map(str::to_owned)
        .collect()
    );
    assert_eq!(scheme.effects.names.len(), 5);
    assert_eq!(scheme.effects.failures.len(), 1);
    let uses = function(&program, "sample").uses.as_ref().unwrap();
    assert_eq!(uses.effects.len(), 6);
    let scoped = uses
        .effects
        .iter()
        .filter_map(|e| e.scope.as_ref())
        .collect::<Vec<_>>();
    assert_eq!(scoped.len(), 4);
    assert_eq!(
        scoped
            .iter()
            .map(|s| slice(&source, s.element_span()))
            .collect::<Vec<_>>(),
        [
            "\"/data/a/**\"",
            "\"/data/a/input\"",
            "\"A.Example\", 0x1_bb",
            "\"192.168.1.0/24\", 80..81"
        ]
    );
    assert_eq!(scoped[0].span, scoped[1].span);
    assert_eq!(scoped[2].span, scoped[3].span);
    assert_eq!(scoped[0].items.len(), 2);
    assert_eq!(scoped[2].items.len(), 4);
    assert_eq!(
        slice(&source, scoped[0].span),
        "[\"/data/a/**\", \"/data/a/input\",]"
    );
    let shown = scheme.fn_ty().show(&TyNames {
        bindings: &program.resolved.bindings,
        adts: &program.types.adts,
        effects: &program.types.effects,
        type_params: &[],
        effect_params: &[],
    });
    for expected in suffixes.iter().filter(|s| !s.is_empty()) {
        assert!(shown.contains(expected), "{shown}");
    }
}

// 関門: 型引数と範囲引数を区別した後も、Failの型代入と関数型の原子を保存する。
// 既存の型APIのテストはソースの注釈を通らず、parser/resolveからの取り落としを捕まえない。
#[test]
fn scoped_function_types_and_failure_arguments_survive_instantiation() {
    let source = format!(
        "{IMPORTS}function identity[T](value: T) -> T uses Failure.Fail[T]\n return value\nend function\nfunction relay[T](body: function(value: T) -> T uses File.Read[\"/data/**\"], value: T) -> T uses File.Read[\"/data/**\"]\n return body(value: value)\nend function\nfunction target(value: Integer) -> Integer uses File.Read[\"/data/**\"]\n return value\nend function\nfunction sample() -> Integer uses File.Read[\"/data/**\"], Failure.Fail[Integer]\n return relay(body: target, value: identity(value: 7))\nend function\n"
    );
    let checked = check(&source);
    assert!(errors(&checked).is_empty(), "{:?}", checked.diagnostics);
    let program = checked.program.unwrap();
    let identity = signature(&program, "identity");
    assert_eq!(identity.effects.failures, [Ty::Param(0)]);
    let relay = signature(&program, "relay");
    let Ty::Fn(callback) = &relay.params[0] else {
        panic!("callback is not a function")
    };
    assert_eq!(callback.effects.names.len(), 1);
    assert_eq!(callback.effects.names[0].range().suffix(), "[\"/data/**\"]");
    let failure = function(&program, "identity")
        .uses
        .as_ref()
        .unwrap()
        .effects
        .first()
        .unwrap();
    assert_eq!(failure.args.as_ref().unwrap().len(), 1);
    assert!(failure.scope.is_none());

    let wrong = source.replace(
        "function target(value: Integer) -> Integer uses File.Read[\"/data/**\"]",
        "function target(value: Integer) -> Integer uses File.Read[\"/other/**\"]",
    );
    let rejected = check(&wrong);
    assert!(rejected.program.is_none());
    let diagnostics = errors(&rejected);
    assert_eq!(
        diagnostics
            .iter()
            .filter_map(|d| d.code.map(|c| c.info().id))
            .collect::<Vec<_>>(),
        ["E0401"],
        "{:?}",
        rejected.diagnostics
    );
    assert!(
        diagnostics[0]
            .primary
            .as_ref()
            .unwrap()
            .text
            .contains("/other/**"),
        "{:?}",
        diagnostics[0]
    );
    assert!(
        diagnostics[0]
            .primary
            .as_ref()
            .unwrap()
            .text
            .contains("/data/**"),
        "{:?}",
        diagnostics[0]
    );
}

// 関門: 不正な注釈を補完・Top化せず、名前の要求する引数の種類に応じて診断する。
// 既存の型引数検査は文字列/組/式を構文段で拒否するため、この診断の分担を確認できない。
#[test]
fn invalid_scopes_are_rejected_by_the_argument_contract() {
    for (setup, annotation, code) in [
        ("", "File.Write[Integer]", "E0520"),
        ("", "File.Write[]", "E0520"),
        ("", "File.Write[0]", "E0520"),
        ("", "File.Write[\"/data\", 443]", "E0520"),
        ("", "File.Write[\"relative\"]", "E0520"),
        ("", "File.Write[\"/data/../file\"]", "E0520"),
        ("", "File.Write[\"/data/*\"]", "E0520"),
        ("", "File.Write[\"${1}\"]", "E0520"),
        ("", "File.Write[\"/data\" + \"/file\"]", "E0520"),
        (
            "const pattern: String = \"/data\"\n",
            "File.Write[pattern]",
            "E0520",
        ),
        ("", "Http.Connect[]", "E0520"),
        ("", "Http.Connect[\"a.example\"]", "E0520"),
        ("", "Http.Connect[443]", "E0520"),
        (
            "",
            "Http.Connect[\"a.example\", 443, \"b.example\"]",
            "E0520",
        ),
        ("", "Http.Connect[\"a.example\", \"443\"]", "E0520"),
        ("", "Http.Connect[\"a.example\", 65536]", "E0520"),
        ("", "Http.Connect[\"a.example\", 443..80]", "E0520"),
        ("", "Http.Connect[\"192.168.1.1/24\", 443]", "E0520"),
        ("", "Http.Connect[\"127.0.0.01\", 443]", "E0520"),
        ("", "Http.Connect[\"2001:0DB8::1\", 443]", "E0520"),
        ("", "Http.Connect[\"[::1]\", 443]", "E0520"),
        ("", "Http.Connect[\"fe80::1%en0\", 443]", "E0520"),
        ("", "Http.Connect[\"**.127.0.0.1\", 443]", "E0520"),
        ("", "Failure.Fail[\"x\"]", "E0513"),
        ("", "Failure.Fail[\"x\", \"y\"]", "E0513"),
        ("", "Failure.Fail[]", "E0513"),
        (
            "effect Local\n function ask() -> Unit\nend effect\n",
            "Local[Integer]",
            "E0513",
        ),
        (
            "effect Local\n function ask() -> Unit\nend effect\n",
            "Local[\"/data\"]",
            "E0513",
        ),
        ("", "IO.All[\"/data\"]", "E0513"),
        ("", "State[\"/data\"]", "E0513"),
    ] {
        let source = format!(
            "{IMPORTS}{setup}function sample() -> Unit uses {annotation}\n ()\nend function\n"
        );
        let result = check(&source);
        assert!(result.program.is_none(), "accepted: {annotation}");
        let diagnostics = errors(&result);
        assert!(
            !diagnostics.is_empty(),
            "{annotation}: {:?}",
            result.diagnostics
        );
        assert!(
            diagnostics
                .iter()
                .all(|d| d.code.is_some_and(|c| c.info().id == code)),
            "{annotation}: {diagnostics:?}"
        );
    }
}

// 関門: 略記内と別群にまたがる重複を、正規化後の同一原子として両位置で示す。
// 集合APIのdedupだけでは、明示重複を黙って消す退行を捕まえない。
#[test]
fn duplicate_atoms_report_both_original_elements() {
    for (annotation, first, repeated) in [
        ("File.Write[\"/data\", \"/data\"]", "\"/data\"", "\"/data\""),
        (
            "File.Write[\"/data\", \"/other\"], File.Write[\"/data\"]",
            "\"/data\"",
            "\"/data\"",
        ),
        (
            "Http.Connect[\"A.Example\", 443, \"a.example\", 443..443]",
            "\"A.Example\", 443",
            "\"a.example\", 443..443",
        ),
        (
            "Http.Connect[\"192.0.2.1/32\", 443], Http.Connect[\"192.0.2.1\", 443]",
            "\"192.0.2.1/32\", 443",
            "\"192.0.2.1\", 443",
        ),
        (
            "Http.Connect[\"::1/128\", 0], Http.Connect[\"::1\", 0]",
            "\"::1/128\", 0",
            "\"::1\", 0",
        ),
    ] {
        let source =
            format!("{IMPORTS}function sample() -> Unit uses {annotation}\n ()\nend function\n");
        let checked = check(&source);
        let diagnostics = errors(&checked);
        assert_eq!(diagnostics.len(), 1, "{annotation}: {diagnostics:?}");
        let diagnostic = diagnostics[0];
        assert_eq!(
            diagnostic.code.unwrap().info().id,
            "E0419",
            "{annotation}: {diagnostic:?}"
        );
        let primary = diagnostic.primary.as_ref().unwrap().span;
        let earlier = diagnostic.secondary.first().unwrap().span;
        assert!(
            earlier.start < primary.start,
            "{annotation}: {diagnostic:?}"
        );
        assert_eq!(slice(&source, earlier), first, "{diagnostic:?}");
        assert_eq!(slice(&source, primary), repeated, "{diagnostic:?}");
    }
}

// 関門: PortArg は既存の IntLit を使う。接尾辞付き字句の取り落としと、
// 接尾辞固有の値域の無視を、通常の注釈の受理と拒否の対で捕まえる。
#[test]
fn port_arguments_use_integer_literal_values_and_widths() {
    for (literal, normalized) in [
        ("0s8", 0),
        ("127s8", 127),
        ("255u8", 255),
        ("443s16", 443),
        ("443s32", 443),
        ("443s64", 443),
        ("443u16", 443),
        ("443u32", 443),
        ("443u64", 443),
        ("0xff_ffu16", 65535),
    ] {
        let source = format!(
            "{IMPORTS}function sample() -> Unit uses Http.Connect[\"example.com\", {literal}]\n ()\nend function\n"
        );
        let checked = check(&source);
        assert!(
            errors(&checked).is_empty(),
            "{literal}: {:?}",
            checked.diagnostics
        );
        let program = checked.program.unwrap();
        assert_eq!(
            signature(&program, "sample").effects.names[0]
                .range()
                .suffix(),
            format!("[\"example.com\", {normalized}]")
        );
    }
    for literal in [
        "128s8",
        "256u8",
        "65535s16",
        "65536u16",
        "18446744073709551615u64",
        "-1",
        "443.0",
        "443m",
    ] {
        let source = format!(
            "{IMPORTS}function sample() -> Unit uses Http.Connect[\"example.com\", {literal}]\n ()\nend function\n"
        );
        let checked = check(&source);
        let diagnostics = errors(&checked);
        assert!(!diagnostics.is_empty(), "accepted {literal}");
        assert!(
            diagnostics
                .iter()
                .all(|d| d.code.is_some_and(|c| c.info().id == "E0520")),
            "{literal}: {diagnostics:?}"
        );
    }
}

// 関門: 範囲引数の構文が通常の値型に範囲を付ける許可へ広がらず、
// 閉じ括弧を失った入力は従来の構文診断で止まることを公開入口で確かめる。
#[test]
fn value_type_scope_misuse_and_unrecoverable_syntax_are_rejected() {
    for ty in [
        "Integer[\"/data\"]",
        "Integer[\"/data\", \"/other\"]",
        "Reference[\"/data\"]",
        "List[Integer[\"/data\"]]",
    ] {
        let source = format!("function sample(value: {ty}) -> Unit\n ()\nend function\n");
        let checked = check(&source);
        let diagnostics = errors(&checked);
        assert!(!diagnostics.is_empty(), "accepted {ty}");
        assert!(
            diagnostics
                .iter()
                .all(|d| d.code.is_some_and(|c| c.info().id == "E0520")),
            "{ty}: {diagnostics:?}"
        );
    }
    let source = format!(
        "{IMPORTS}function sample() -> Unit uses File.Write[\"/data\"\n ()\nend function\n"
    );
    let checked = check(&source);
    let diagnostics = errors(&checked);
    assert!(!diagnostics.is_empty());
    assert!(
        diagnostics.iter().all(|d| d
            .code
            .is_some_and(|c| c.info().id.starts_with("E01") || c.info().id.starts_with("E02"))),
        "{diagnostics:?}"
    );
}
